data = _items[0]["json"]

requests = data["output"]["requests"]
categories = data["categories"]

for request in requests:
    category = request["category"]
    subcategory = request["subcategory"]

    if category in categories and subcategory in categories[category]:
        request["valid"] = True
    else:
        request["valid"] = False

return [
  {
    "json": {
      "requests": requests,
      "requires_attention": data["output"]["requires_attention"] or any(
      not request["valid"] for request in requests)
    }
  }
]

